package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen2Test {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() throws IOException {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

















    @Test
    public void testChainedValueMethods() throws IOException {
        jsonWriter.beginObject().name("first").value(1.0).name("second").value(2.0).endObject();
        assertEquals("{\"first\":1.0,\"second\":2.0}", stringWriter.toString().trim());
    }
}
